/**
 * Main Application Router Configuration
 *
 * Route definitions are loaded from routes.config.tsx which is
 * generated by the Genesis pipeline. This file owns the shell
 * (Layout, ErrorBoundary, RouterProvider) and is never overwritten.
 *
 * React 19 + React Router v7 best practices:
 * - Error boundary at root level
 * - Layout wraps all child routes
 * - Named `router` export for DevTools integration
 */

import { createBrowserRouter, RouterProvider } from "react-router";
import { Layout } from "./components/Layout";
import { ErrorBoundary } from "./components/ErrorBoundary";
import { routes } from "./routes.config";

export const router = createBrowserRouter([
  {
    path: "/",
    element: <Layout />,
    errorElement: <ErrorBoundary />,
    children: routes,
  },
]);

function App() {
  return <RouterProvider router={router} />;
}

export default App;
